import sqlite3
import json
import re

conn = sqlite3.connect('/root/data/eventlogs.db')
cur = conn.cursor()

malicious_guids = {'{297bc33e-65d0-5f2d-8207-000000000400}', '{297bc33e-660d-5f2d-8407-000000000400}'}
malicious_pids = {1648, 6504}
malicious_pids_hex = {'0x670', '0x1968'}

candidates = []

cur.execute("SELECT event_id, event_code, timestamp, host, user, image, target_image, process_guid, message FROM events;")
rows = cur.fetchall()

for r in rows:
    eid, ec, ts, host, user, img, tgt_img, pguid, msg = r

    is_malicious = False
    reason = ""

    # 1. Matches malicious process GUIDs directly
    if pguid in malicious_guids:
        is_malicious = True
        reason = f"Process GUID match ({pguid})"

    # 2. Event ID 800 or 4103 (already verified to belong to malicious powershell)
    elif ec in (800, 4103) and host == 'WS-05.corp.example':
        is_malicious = True
        reason = "PowerShell execution event on WS-05"

    # 3. Source process is malicious powershell/whoami
    elif img and ('powershell' in img.lower() or 'whoami' in img.lower()) and host == 'WS-05.corp.example':
        if pguid in malicious_guids or '1648' in msg or '6504' in msg:
            is_malicious = True
            reason = "Malicious image and PID/GUID match in message"

    # 4. Process Access (Event 10) initiated by powershell.exe (PID 1648)
    elif ec == 10 and host == 'WS-05.corp.example':
        if 'SourceProcessGUID: {297bc33e-65d0-5f2d-8207-000000000400}' in msg or 'SourceProcessId: 1648' in msg:
            is_malicious = True
            reason = "Process Access initiated by malicious process"

    # 5. Security event for process creation (4688) or termination (4689)
    elif ec in (4688, 4689) and host == 'WS-05.corp.example':
        if 'whoami.exe' in msg or '6504' in msg or '0x1968' in msg or '1648' in msg or '0x670' in msg:
            is_malicious = True
            reason = f"Security process event ({ec}) for malicious process"

    # 6. Windows Filtering Platform (5156, 5158) related to powershell
    elif ec in (5156, 5158) and host == 'WS-05.corp.example':
        if '1648' in msg or 'powershell.exe' in msg.lower():
            is_malicious = True
            reason = f"WFP event ({ec}) for malicious process"

    # 7. Other Sysmon events (Registry, named pipes, DNS, etc.)
    else:
        # check if process_guid or process_id matches inside the message
        for line in msg.split('\n'):
            if 'ProcessGuid:' in line:
                g = line.split(':', 1)[1].strip().replace('{','').replace('}','')
                g_full = '{' + g + '}'
                if g_full in malicious_guids:
                    is_malicious = True
                    reason = f"Process GUID inside message match ({g_full})"
            if 'ProcessId:' in line:
                pid_str = line.split(':', 1)[1].strip()
                try:
                    pid_val = int(pid_str)
                    if pid_val in malicious_pids:
                        is_malicious = True
                        reason = f"Process ID inside message match ({pid_val})"
                except ValueError:
                    pass

    if is_malicious:
        candidates.append({
            "event_id": eid,
            "event_code": ec,
            "timestamp": ts,
            "host": host,
            "image": img,
            "target_image": tgt_img,
            "reason": reason
        })

print(f"Total malicious candidate events found: {len(candidates)}")
ec_counts = {}
for c in candidates:
    ec = c["event_code"]
    ec_counts[ec] = ec_counts.get(ec, 0) + 1

for ec, count in sorted(ec_counts.items()):
    print(f"  Event Code {ec}: {count}")

# Save all candidates to /tmp/mal_events.json
with open('/tmp/mal_events.json', 'w') as f:
    json.dump(candidates, f, indent=2)

